import pandas as pd
import os

files = [
    "experiment_1_csv", "experiment_2_csv", "experiment_3_csv",
    "experiment_4_csv", "experiment_5_csv", "experiment_6_csv"
]

for fname in files:
    if fname in globals():
        path = globals()[fname]
        if os.path.exists(path):
            df = pd.read_csv(path)
            print(f"--- {fname} ---")
            print(f"Shape: {df.shape}, Columns: {list(df.columns)}")
            print(df.describe().round(2))
            print()
        else:
            print(f"{fname}: file not found")
