        print(f"{fname}: not defined")

import pandas as pd
import os

print("Directory contents:", os.listdir('.'))

for i in range(1, 7):
    vname = f"experiment_{i}_csv"
    if vname in globals():
        p = globals()[vname]
        print(f"\n--- {vname} (path={p}) ---")
        try:
            df = pd.read_csv(p)
            print("Columns:", list(df.columns))
            num = df.select_dtypes('number').columns
            if len(num) > 0:
                print("Means:", df[num].mean().round(3))
        except Exception as e:
            print(f"Load failed: {e}")
    else:
        print(f"{vname} not found in globals")
